contracts.body:
def acquire_canonical_events(league, timeout=15, root=None):
    league = str(league).upper()
    if league not in ADMITTED:
        raise RuntimeError(f'league not admitted: {league}')
    if league in ('NFL', 'NCAAF', 'NBA'):
        return _legacy(league, timeout)
    return _promoted(league, timeout, root)
